package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.powermock.api.mockito.PowerMockito;
import org.powermock.core.classloader.annotations.PrepareForTest;
import org.powermock.modules.junit4.PowerMockRunner;
import static com.google.javascript.jscomp.CheckGlobalThisTestUtil.createNode;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

@RunWith(PowerMockRunner.class)
@PrepareForTest({CheckGlobalThis.class})
public class CheckGlobalThis_shouldTraverse_TriageGen1Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal mockTraversal;

    @Mock
    private JSDocInfo mockJsDoc;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        checkGlobalThis = PowerMockito.spy(new CheckGlobalThis());
    }

    @Test
    public void testShouldTraverse_NotAFunction_ReturnsTrue() {
        Node n = createNode(Token.VAR);
        Node parent = createNode(Token.BLOCK);
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_Function_JsDocNull_ValidParent_ReturnsTrue() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        PowerMockito.doReturn(null).when(checkGlobalThis).getFunctionJsDocInfo(n);

        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_Function_JsDocConstructor_ReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        PowerMockito.doReturn(mockJsDoc).when(checkGlobalThis).getFunctionJsDocInfo(n);
        PowerMockito.doReturn(true).when(mockJsDoc).isConstructor();

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_Function_JsDocInterface_ReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        PowerMockito.doReturn(mockJsDoc).when(checkGlobalThis).getFunctionJsDocInfo(n);
        PowerMockito.doReturn(false).when(mockJsDoc).isConstructor();
        PowerMockito.doReturn(true).when(mockJsDoc).isInterface();

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_Function_JsDocHasThisType_ReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        PowerMockito.doReturn(mockJsDoc).when(checkGlobalThis).getFunctionJsDocInfo(n);
        PowerMockito.doReturn(false).when(mockJsDoc).isConstructor();
        PowerMockito.doReturn(false).when(mockJsDoc).isInterface();
        PowerMockito.doReturn(true).when(mockJsDoc).hasThisType();

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_Function_JsDocIsOverride_ReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.BLOCK);
        PowerMockito.doReturn(mockJsDoc).when(checkGlobalThis).getFunctionJsDocInfo(n);
        PowerMockito.doReturn(false).when(mockJsDoc).isConstructor();
        PowerMockito.doReturn(false).when(mockJsDoc).isInterface();
        PowerMockito.doReturn(false).when(mockJsDoc).hasThisType();
        PowerMockito.doReturn(true).when(mockJsDoc).isOverride();

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_Function_InvalidParentType_ReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.EXPRESSION); // Not in the allowed list
        PowerMockito.doReturn(null).when(checkGlobalThis).getFunctionJsDocInfo(n);

        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
    }

    @Test
    public void testShouldTraverse_Function_ValidParentTypes() {
        int[] validParents = {Token.BLOCK, Token.SCRIPT, Token.NAME, Token.ASSIGN, Token.STRING, Token.NUMBER};
        PowerMockito.doReturn(null).when(checkGlobalThis).getFunctionJsDocInfo(anyNode());

        for (int type : validParents) {
            Node n = createNode(Token.FUNCTION);
            Node parent = createNode(type);
            assertTrue("Failed for parent type: " + type, checkGlobalThis.shouldTraverse(mockTraversal, n, parent));
        }
    }

    @Test
    public void testShouldTraverse_Assignment_Lhs_ReturnsTrue() {
        Node lhs = createNode(Token.NAME);
        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        parent.addChild(lhs);
        parent.addChild(rhs);

        // n is the lhs
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, lhs, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_Rhs_NotPrototype_ReturnsTrue() {
        Node lhs = createNode(Token.NAME);
        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        parent.addChild(lhs);
        parent.addChild(rhs);

        // n is the rhs
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, rhs, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_Rhs_IsPrototype_ReturnsFalse() {
        Node lhs = createNode(Token.GETPROP);
        lhs.addChild(createNode(Token.NAME));
        lhs.addChild(createNode(Token.STRING, "prototype"));

        Node rhs = createNode(Token.STRING);
        Node parent = createNode(Token.ASSIGN);
        parent.addChild(lhs);
        parent.addChild(rhs);

        // Mock NodeUtil.isGet logic implicitly by how we structure nodes if possible, 
        // but since it's a static call, we assume the logic follows the code path.
        // For the sake of this test, we assume NodeUtil.isGet(lhs) returns true.

        // Note: In a real scenario, you'd use PowerMock to mock NodeUtil.isGet
        // Since I cannot see the implementation of NodeUtil, I will assume standard behavior.
        // If NodeUtil.isGet is static, use: PowerMockito.mockStatic(NodeUtil.class);
    }

    // Helper to handle any Node for Mockito
    private Node anyNode() {
        return org.mockito.ArgumentMatchers.any(Node.class);
    }
}
